import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"guides/quick-start.md","filePath":"guides/quick-start.md","lastUpdated":1788855895000}'),n={name:"guides/quick-start.md"};function r(o,e,l,h,d,p){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>Get a working Memoh in about ten minutes: deploy the server, sign in, add a model provider, create your first bot, and connect it to a chat channel.</p><div class="tip custom-block"><p class="custom-block-title">Prefer not to self-host?</p><p><a href="https://memoh.ai" target="_blank" rel="noreferrer">Memoh Cloud</a> runs the same product as a hosted service. Skip to <a href="#step-3-add-a-model-provider">Step 3</a> once you have signed in.</p></div><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A Linux server or workstation with <strong>Docker</strong> and <strong>Docker Compose</strong> installed.</li><li>An API key for at least one LLM provider (OpenAI, Anthropic, DeepSeek, Zhipu, ...) or a local Ollama instance.</li><li>Ports <strong>8080</strong> (API) and <strong>8082</strong> (Web UI) reachable from your browser.</li></ul><h2 id="step-1-deploy-the-server" tabindex="-1">Step 1: Deploy the server <a class="header-anchor" href="#step-1-deploy-the-server" aria-label="Permalink to &quot;Step 1: Deploy the server&quot;">​</a></h2><p>The one-line installer pulls the images, generates a <code>config.toml</code>, and starts everything with Docker Compose:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://memoh.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><p>Users in mainland China can enable the mirror:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://memoh.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> USE_CN_MIRROR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Do not run the whole installer with <code>sudo</code></p><p>The installer will call <code>sudo docker</code> on its own when your user is not in the <code>docker</code> group.</p></div><p>Prefer to do it by hand? Clone the repository and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/felinics/Memoh.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Memoh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> conf/app.docker.toml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.toml</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># edit config.toml (admin password, JWT secret, ...)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>When it finishes you should see:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>🌐 Web UI:      http://localhost:8082</span></span>
<span class="line"><span>🔌 API:         http://localhost:8080</span></span>
<span class="line"><span>🔑 Admin login: admin / &lt;your password&gt;</span></span></code></pre></div><p>Read <a href="/self-hosted/docker.html">Server Deploy</a> for production hardening, reverse proxies, and upgrades.</p><h2 id="step-2-sign-in" tabindex="-1">Step 2: Sign in <a class="header-anchor" href="#step-2-sign-in" aria-label="Permalink to &quot;Step 2: Sign in&quot;">​</a></h2><p>Open <code>http://&lt;your-server&gt;:8082</code> and sign in with the admin account you chose during install (the default in <code>conf/app.docker.toml</code> is <code>admin</code> / <code>admin123</code>). Change the password right away under <strong>Settings → Account</strong>.</p><h2 id="step-3-add-a-model-provider" tabindex="-1">Step 3: Add a model provider <a class="header-anchor" href="#step-3-add-a-model-provider" aria-label="Permalink to &quot;Step 3: Add a model provider&quot;">​</a></h2><ol><li>Go to <strong>Providers</strong> in the sidebar and click <strong>Add Provider</strong>.</li><li>Pick a template (OpenAI, Anthropic, Gemini, DeepSeek, Zhipu, OpenRouter, Ollama, ...) and paste your API key.</li><li>Open the provider and <strong>sync</strong> or add at least one chat model.</li></ol><p>Details and client types are in <a href="/integrations/providers/llm.html">LLM Providers</a>.</p><h2 id="step-4-create-your-first-bot" tabindex="-1">Step 4: Create your first bot <a class="header-anchor" href="#step-4-create-your-first-bot" aria-label="Permalink to &quot;Step 4: Create your first bot&quot;">​</a></h2><ol><li>Go to <strong>Bots → New Bot</strong>, give it a name and a display name.</li><li>In the bot&#39;s <strong>General</strong> tab choose the chat model you just added.</li><li>Click the bot&#39;s <strong>Chat</strong> button and say hello. If you get a reply, the pipeline works.</li></ol><p>Each bot has its own workspace, memory, and settings; see <a href="/guides/bot.html">Bot</a> for every tab.</p><h2 id="step-5-connect-a-channel" tabindex="-1">Step 5: Connect a channel <a class="header-anchor" href="#step-5-connect-a-channel" aria-label="Permalink to &quot;Step 5: Connect a channel&quot;">​</a></h2><ol><li>Open the bot&#39;s <strong>Channels</strong> tab and click <strong>Add</strong>.</li><li>Pick a platform (Telegram, Discord, Slack, Feishu, DingTalk, WeCom, QQ, LINE, Matrix, Misskey, ...) and paste the platform credentials.</li><li>Message the bot from that platform. The first message creates a session; use <code>/help</code> to see the available slash commands.</li></ol><p>Per-platform setup guides live under <a href="/integrations/channels/">Channels</a>.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Read</th></tr></thead><tbody><tr><td>Let the bot remember users across sessions</td><td><a href="/guides/memory.html">Memory</a></td></tr><tr><td>Run scheduled or recurring tasks</td><td><a href="/guides/schedule.html">Schedule</a></td></tr><tr><td>Give the bot files, shell access, and a browser</td><td><a href="/guides/container.html">Workspace</a>, <a href="/guides/computers.html">Computers</a></td></tr><tr><td>Add tools via MCP servers</td><td><a href="/guides/mcp.html">MCP</a></td></tr><tr><td>Teach the bot reusable procedures</td><td><a href="/guides/skills.html">Skills</a>, <a href="/guides/supermarket.html">Supermarket</a></td></tr><tr><td>Control who can talk to the bot</td><td><a href="/guides/access.html">Access Control</a></td></tr><tr><td>Run everything on a Mac with the desktop app</td><td><a href="/self-hosted/desktop.html">Desktop</a></td></tr></tbody></table>`,29)])])}const u=t(n,[["render",r]]);export{k as __pageData,u as default};
